use std::fs;
use std::path::Path;
use toml::{Table, Value};

/// Generated manifest, relative to the project root
pub const MANIFEST: &str = ".yawn/Cargo.toml";
/// Lockfile of the generated manifest; kept in step with the project's own `Cargo.lock`
pub const LOCK: &str = ".yawn/Cargo.lock";

const HEADER: &str =
    "# @generated by yawn from ../Cargo.toml. Do not edit; changes are overwritten.\n";

fn fix_paths(deps: &mut Value, up: &str) {
    let Some(table) = deps.as_table_mut() else {
        return;
    };
    for dep in table.iter_mut().map(|(_, v)| v) {
        if let Some(path) = dep.as_table_mut().and_then(|t| t.get_mut("path"))
            && let Some(p) = path.as_str()
            && !Path::new(p).is_absolute()
        {
            *path = Value::String(format!("{up}{p}"));
        }
    }
}

fn router_dependency(deps: &Table) -> Result<Value, String> {
    let fail = || {
        "folder routing needs `yawn-router` in [dependencies] (next to `yawn-web`, same version or path)".to_string()
    };
    match deps.get("yawn-web").ok_or_else(fail)? {
        Value::String(v) => Ok(Value::String(v.clone())),
        Value::Table(t) => {
            let mut out = Table::new();
            if let Some(path) = t.get("path").and_then(Value::as_str) {
                let trimmed = path.trim_end_matches('/');
                let base = trimmed.strip_suffix("yawn-web").ok_or_else(fail)?;
                out.insert("path".into(), Value::String(format!("{base}yawn-router")));
                return Ok(Value::Table(out));
            }
            for key in ["version", "git", "branch", "tag", "rev", "registry"] {
                if let Some(v) = t.get(key) {
                    out.insert(key.into(), v.clone());
                }
            }
            if out.is_empty() {
                return Err(fail());
            }
            Ok(Value::Table(out))
        }
        _ => Err(fail()),
    }
}

/// The project's package name, from its `Cargo.toml`
pub fn package_name(root: &Path) -> Option<String> {
    let t: Table = fs::read_to_string(root.join("Cargo.toml")).ok()?.parse().ok()?;
    t.get("package")?.get("name")?.as_str().map(str::to_string)
}

/// Crate name of the generated library: the server binary renders `yawn_app::App`
pub const LIB_NAME: &str = "yawn_app";

/// The manifest text for the user's `Cargo.toml`
pub fn generate(user: &str, router: bool) -> Result<String, String> {
    generate_split(user, router, &[])
}

/// A generated crate below the root one: its directory name below `.yawn/crates/` and the directory
/// names of the crates it uses
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Member {
    pub dir: String,
    pub deps: Vec<String>,
}

/// Package name of the member crate in `dir`, for the project package `pkg`
pub fn member_package(pkg: &str, dir: &str) -> String {
    format!("{MEMBER_PREFIX}{pkg}-{dir}")
}

pub const MEMBER_PREFIX: &str = "yawn-split-";

/// [`generate`] for a project whose modules were split into the crates `members`: the root package
/// uses all of them
pub fn generate_split(user: &str, router: bool, members: &[Member]) -> Result<String, String> {
    let (mut t, name) = base_table(user, router, "../")?;
    for m in members {
        let mut dep = Table::new();
        dep.insert("path".into(), Value::String(format!("crates/{}", m.dir)));
        let deps = t.entry("dependencies").or_insert_with(|| Value::Table(Table::new()));
        if let Some(deps) = deps.as_table_mut() {
            deps.insert(member_package(&name, &m.dir), Value::Table(dep));
        }
    }
    finish_root(&mut t, &name);
    Ok(format!("{HEADER}{}", toml::to_string(&t).map_err(|e| e.to_string())?))
}

/// The manifest of the member crate `member`: the project's dependencies, a library, and the crates
/// it uses
pub fn generate_member(user: &str, router: bool, member: &Member) -> Result<String, String> {
    let (mut t, name) = base_table(user, router, "../../../")?;
    let pkg = member_package(&name, &member.dir);
    if let Some(p) = t.get_mut("package").and_then(Value::as_table_mut) {
        p.insert("name".into(), Value::String(pkg));
        p.insert("publish".into(), Value::Boolean(false));
    }
    t.remove("profile");
    t.remove("patch");
    for dep in &member.deps {
        let mut d = Table::new();
        d.insert("path".into(), Value::String(format!("../{dep}")));
        let deps = t.entry("dependencies").or_insert_with(|| Value::Table(Table::new()));
        if let Some(deps) = deps.as_table_mut() {
            deps.insert(member_package(&name, dep), Value::Table(d));
        }
    }
    let mut lib = Table::new();
    lib.insert("path".into(), "lib.rs".into());
    t.insert("lib".into(), Value::Table(lib));
    sources_target(&mut t, "../../../src/yawn-sources.rs", None);
    t.insert("workspace".into(), Value::Table(Table::new()));
    t.remove("workspace");
    Ok(format!("{HEADER}{}", toml::to_string(&t).map_err(|e| e.to_string())?))
}

fn sources_target(t: &mut Table, path: &str, bin: Option<Value>) {
    let mut sources = Table::new();
    sources.insert("name".into(), "yawn-sources".into());
    sources.insert("path".into(), path.into());
    sources.insert("required-features".into(), Value::Array(vec!["yawn-never".into()]));
    for off in ["test", "doc", "bench"] {
        sources.insert(off.into(), Value::Boolean(false));
    }
    let mut bins = Vec::new();
    bins.extend(bin);
    bins.push(Value::Table(sources));
    t.insert("bin".into(), Value::Array(bins));
    let features = t.entry("features").or_insert_with(|| Value::Table(Table::new()));
    if let Some(features) = features.as_table_mut() {
        features.insert("yawn-never".into(), Value::Array(Vec::new()));
    }
}

fn base_table(user: &str, router: bool, up: &str) -> Result<(Table, String), String> {
    let mut t: Table = user.parse().map_err(|e: toml::de::Error| format!("Cargo.toml: {e}"))?;
    let name = t
        .get("package")
        .and_then(|p| p.get("name"))
        .and_then(Value::as_str)
        .ok_or("Cargo.toml: missing [package] name")?
        .to_string();
    for key in ["lib", "bin", "example", "test", "bench", "workspace"] {
        t.remove(key);
    }
    if let Some(p) = t.get_mut("package").and_then(Value::as_table_mut) {
        p.remove("build");
        p.remove("autolib");
        p.remove("autobins");
    }
    if router {
        let deps = t.entry("dependencies").or_insert_with(|| Value::Table(Table::new()));
        if let Some(deps) = deps.as_table_mut()
            && !deps.contains_key("yawn-router")
        {
            let dep = router_dependency(deps)?;
            deps.insert("yawn-router".into(), dep);
        }
    }
    for key in ["dependencies", "dev-dependencies", "build-dependencies"] {
        if let Some(d) = t.get_mut(key) {
            fix_paths(d, up);
        }
    }
    if let Some(targets) = t.get_mut("target").and_then(Value::as_table_mut) {
        for cfg in targets.iter_mut().map(|(_, v)| v).filter_map(Value::as_table_mut) {
            for key in ["dependencies", "dev-dependencies", "build-dependencies"] {
                if let Some(d) = cfg.get_mut(key) {
                    fix_paths(d, up);
                }
            }
        }
    }
    if let Some(patches) = t.get_mut("patch").and_then(Value::as_table_mut) {
        for registry in patches.iter_mut().map(|(_, v)| v) {
            fix_paths(registry, up);
        }
    }
    Ok((t, name))
}

fn finish_root(t: &mut Table, name: &str) {
    let mut lib = Table::new();
    lib.insert("name".into(), LIB_NAME.into());
    lib.insert("path".into(), "client.rs".into());
    lib.insert("crate-type".into(), Value::Array(vec!["cdylib".into(), "rlib".into()]));
    t.insert("lib".into(), Value::Table(lib));
    let mut bin = Table::new();
    bin.insert("name".into(), name.into());
    bin.insert("path".into(), "server.rs".into());
    // A target that's never built, so rust-analyzer treats the project's `src/` as a source root
    sources_target(t, "../src/yawn-sources.rs", Some(Value::Table(bin)));
    // Its own workspace: otherwise cargo would look for one in the project's `Cargo.toml`.
    t.insert("workspace".into(), Value::Table(Table::new()));
}

/// Writes `.yawn/Cargo.toml` when it changed; returns whether it did
pub fn write(root: &Path, router: bool, members: &[Member]) -> Result<bool, String> {
    let user = fs::read_to_string(root.join("Cargo.toml"))
        .map_err(|e| format!("cannot read Cargo.toml: {e}"))?;
    let text = generate_split(&user, router, members)?;
    let path = root.join(MANIFEST);
    fs::create_dir_all(root.join(".yawn")).map_err(|e| e.to_string())?;
    let mut changed = fs::read_to_string(&path).map_or(true, |old| old != text);
    if changed {
        fs::write(&path, text).map_err(|e| format!("cannot write {MANIFEST}: {e}"))?;
    }
    for m in members {
        let text = generate_member(&user, router, m)?;
        let path = root.join(".yawn/crates").join(&m.dir).join("Cargo.toml");
        if fs::read_to_string(&path).map_or(true, |old| old != text) {
            fs::create_dir_all(path.parent().unwrap()).map_err(|e| e.to_string())?;
            fs::write(&path, text).map_err(|e| format!("cannot write {}: {e}", path.display()))?;
            changed = true;
        }
    }
    let (own, r#gen) = (root.join("Cargo.lock"), root.join(LOCK));
    if own.is_file() && !r#gen.is_file() {
        let _ = fs::copy(&own, &r#gen);
    }
    Ok(changed)
}

/// The lockfile without the generated member crates (their `[[package]]` blocks and the lines that
/// list them as dependencies): the project's own `Cargo.lock` knows nothing of them
pub fn strip_members(lock: &str) -> String {
    let mut out = String::with_capacity(lock.len());
    let mut skipping = false;
    for line in lock.split_inclusive('\n') {
        if line.starts_with("[[package]]") {
            skipping = false;
        }
        if line.starts_with(&format!("name = \"{MEMBER_PREFIX}")) {
            // the block began at the `[[package]]` line already copied: take it back
            let cut = out.rfind("[[package]]").unwrap_or(out.len());
            out.truncate(cut);
            skipping = true;
        }
        if skipping || line.trim_start().starts_with(&format!("\"{MEMBER_PREFIX}")) {
            continue;
        }
        out.push_str(line);
    }
    out
}

/// Copies the lockfile cargo updated in `.yawn/` back to the project's `Cargo.lock`
pub fn sync_lock_back(root: &Path) {
    let (own, r#gen) = (root.join("Cargo.lock"), root.join(LOCK));
    if let Ok(new) = fs::read_to_string(&r#gen) {
        let new = strip_members(&new);
        if fs::read_to_string(&own).ok().as_deref() != Some(new.as_str()) {
            let _ = fs::write(&own, new);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn injects_targets_and_shifts_relative_paths() {
        let out = generate(
            "[package]\nname = \"app\"\nversion = \"0.1.0\"\n[dependencies]\nyawn-web = { path = \"../../crates/yawn-web\" }\nserde = \"1\"\n\
             [profile.dev]\nopt-level = \"s\"\n[workspace]\n",
            false,
        )
        .unwrap();
        let t: Table = out.parse().unwrap();
        assert_eq!(t["lib"]["path"].as_str(), Some("client.rs"));
        assert_eq!(t["bin"][0]["name"].as_str(), Some("app"));
        assert_eq!(t["bin"][0]["path"].as_str(), Some("server.rs"));
        assert_eq!(
            t["dependencies"]["yawn-web"]["path"].as_str(),
            Some("../../../crates/yawn-web")
        );
        assert_eq!(t["dependencies"]["serde"].as_str(), Some("1"));
        assert_eq!(t["profile"]["dev"]["opt-level"].as_str(), Some("s"));
        assert!(t["workspace"].as_table().unwrap().is_empty());
    }

    #[test]
    fn member_crates_stay_out_of_the_project_lockfile() {
        let lock = "version = 4\n\n[[package]]\nname = \"app\"\nversion = \"0.1.0\"\ndependencies = [\n \"serde\",\n \"yawn-split-app-ui\",\n]\n\n[[package]]\nname = \"serde\"\nversion = \"1.0.0\"\n\n[[package]]\nname = \"yawn-split-app-ui\"\nversion = \"0.1.0\"\ndependencies = [\n \"serde\",\n]\n\n[[package]]\nname = \"zzz\"\nversion = \"1.0.0\"\n";
        let out = strip_members(lock);
        assert!(
            !out.contains("yawn-split")
                && out.contains("name = \"zzz\"")
                && out.contains("\"serde\","),
            "{out}"
        );
        assert_eq!(strip_members(&out), out);
    }

    #[test]
    fn user_targets_do_not_leak_through() {
        let out = generate("[package]\nname = \"a\"\n[lib]\npath = \"src/x.rs\"\n[[bin]]\nname = \"other\"\npath = \"src/o.rs\"\n", false).unwrap();
        let t: Table = out.parse().unwrap();
        assert_eq!(t["lib"]["path"].as_str(), Some("client.rs"));
        // the server and the never-built target that puts `src/` in rust-analyzer's sources; not `other`
        let bins: Vec<_> =
            t["bin"].as_array().unwrap().iter().map(|b| b["name"].as_str().unwrap()).collect();
        assert_eq!(bins, ["a", "yawn-sources"]);
        assert_eq!(t["bin"][1]["required-features"][0].as_str(), Some("yawn-never"));
        assert!(t["features"].as_table().unwrap().contains_key("yawn-never"));
    }

    #[test]
    fn router_dependency_follows_yawn_web() {
        let t = |user: &str| generate(user, true).map(|o| o.parse::<Table>().unwrap());
        let path = t("[package]\nname = \"a\"\n[dependencies]\nyawn-web = { path = \"../../crates/yawn-web\" }\n").unwrap();
        assert_eq!(
            path["dependencies"]["yawn-router"]["path"].as_str(),
            Some("../../../crates/yawn-router")
        );
        let ver = t("[package]\nname = \"a\"\n[dependencies]\nyawn-web = \"0.2\"\n").unwrap();
        assert_eq!(ver["dependencies"]["yawn-router"].as_str(), Some("0.2"));
        let own = t(
            "[package]\nname = \"a\"\n[dependencies]\nyawn-web = \"0.2\"\nyawn-router = \"0.3\"\n",
        )
        .unwrap();
        assert_eq!(
            own["dependencies"]["yawn-router"].as_str(),
            Some("0.3"),
            "an explicit entry wins"
        );
        assert!(t("[package]\nname = \"a\"\n").is_err());
        assert!(
            t("[package]\nname = \"a\"\n[dependencies]\nyawn-web = { path = \"../elsewhere\" }\n")
                .is_err()
        );
    }
}
